// Edit only the two startUrls to try your own public, server-rendered pages.
// No API token belongs in this node. Select Header Auth in the HTTP nodes.
const input = {
  startUrls: ['https://makorev.com/', 'https://makorev.com/blog/google-ads-competitor-tracking'],
  maxPages: 2,
  followLinks: false,
  useProxy: false,
  exportFormat: 'markdown-and-chunks',
  maxTextLength: 30000,
  maxMarkdownLength: 50000,
  chunkMaxCharacters: 2000,
};
if (!Array.isArray(input.startUrls) || input.startUrls.length < 1 || input.startUrls.length > 10) {
  throw new Error('Provide 1–10 explicit public page URLs. This starter does not follow links.');
}
const urls = input.startUrls.map(value => {
  // n8n's Code sandbox does not expose the URL constructor. Check a conservative
  // HTTP(S) shape here; the Actor performs full URL validation before crawling.
  const match = typeof value === 'string' && value.match(/^https?:\/\/([^/?#\s]+)([^\s]*)$/i);
  if (!match || match[1].includes('@') || value.includes('\\')) {
    throw new Error('Use public HTTP(S) page URLs without credentials.');
  }
  return value.split('#')[0];
});
if (new Set(urls).size !== urls.length) throw new Error('Remove duplicate input URLs.');
input.startUrls = urls;
input.maxPages = urls.length;
return [{ json: {
  input,
  runOptions: { build: '0.2.2', memory: 512, timeout: 180, maxTotalChargeUsd: 0.10 },
  pollingDeadline: Date.now() + 240000,
} }];

const config = $('Configure crawl').first().json;
const start = $('Start bounded crawl').first().json.data;
const candidate = $input.first().json.data;
const valid = candidate && typeof candidate.id === 'string' && candidate.id === start?.id;
if (!valid) return [{ json: { finished: false, stopPolling: true, reason: 'The run-status response was missing or invalid. An abort is attempted; inspect the run in Apify Console before retrying.' } }];
const statuses = ['READY', 'RUNNING', 'SUCCEEDED', 'FAILED', 'TIMING-OUT', 'TIMED-OUT', 'ABORTING', 'ABORTED'];
if (!statuses.includes(candidate.status)) return [{ json: { finished: false, stopPolling: true, reason: 'Unknown run status. An abort is attempted; inspect Apify Console before retrying.' } }];
const finished = ['SUCCEEDED', 'FAILED', 'TIMED-OUT', 'ABORTED'].includes(candidate.status);
const stopPolling = !finished && (Date.now() >= config.pollingDeadline || $runIndex >= 80);
return [{ json: { run: candidate, finished, stopPolling, reason: stopPolling ? 'Polling deadline exceeded. An abort is attempted; inspect Apify Console before retrying.' : '' } }];

const result = $input.first().json;
if (result.run?.status !== 'SUCCEEDED') throw new Error('The crawl did not succeed. Check the run in Apify Console; this starter will not send partial output downstream.');
if (!/^[A-Za-z0-9]+$/.test(result.run.defaultDatasetId || '') || !/^[A-Za-z0-9]+$/.test(result.run.defaultKeyValueStoreId || '')) {
  throw new Error('The successful run did not return valid output storage IDs.');
}
return [{ json: result }];

const report = $input.first().json;
const expected = $('Configure crawl').first().json.input.startUrls.length;
const reasons = [];
if (report.outcome !== 'succeeded') reasons.push('report outcome is not succeeded');
if (report.fatalError !== null) reasons.push('fatal error or missing fatal-error field');
for (const key of ['failedRequestCount', 'unprocessedInputCount', 'skippedDueToLimitCount', 'pendingRequestCount', 'truncatedPageCount']) {
  if (report[key] !== 0) reasons.push(key + ' is not zero');
}
for (const key of ['markdownTruncatedPageCount', 'emptyMarkdownPageCount']) {
  if (report.aiExport?.[key] !== 0) reasons.push(key + ' is not zero');
}
if (report.requestedUniqueUrlCount !== expected || report.returnedPageCount !== expected) reasons.push('supplied URL count does not match returned page count');
if (report.followLinks !== false) reasons.push('unexpected link-following setting');
if (report.aiExport?.format !== 'markdown-and-chunks') reasons.push('unexpected export format');
if (reasons.length) throw new Error('Coverage check failed: ' + reasons.join('; ') + '. Review RUN_SUMMARY in Apify Console.');
// pageLimitReached alone does not indicate missing pages when all supplied URLs returned.
// Oversized code/table chunks are retained and flagged, not silently split or discarded.
return [{ json: { report } }];

const report = $('Check crawl coverage').first().json.report;
const pages = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
if (pages.length !== report.returnedPageCount) throw new Error('Dataset page count differs from RUN_SUMMARY. No source packets emitted.');
const packets = [];
const seen = new Set();
let oversizedCount = 0;
for (const page of pages) {
  if (!Number.isInteger(page.httpStatusCode) || page.httpStatusCode < 200 || page.httpStatusCode >= 300 || !page.markdown?.trim() || page.markdownTruncated !== false || page.textTruncated !== false) {
    throw new Error('A page is unsuccessful, empty, or truncated. Inspect the dataset before ingestion.');
  }
  if (!Array.isArray(page.chunks) || page.chunks.length < 1 || page.chunkCount !== page.chunks.length) throw new Error('Missing or inconsistent page chunks.');
  for (const chunk of page.chunks) {
    if (!/^[a-f0-9]{64}$/.test(chunk.id || '') || !/^[a-f0-9]{64}$/.test(chunk.contentHash || '') || typeof chunk.content !== 'string' || !chunk.content.trim() || !Array.isArray(chunk.headingPath) || !chunk.headingPath.every(h => typeof h === 'string') || typeof chunk.oversized !== 'boolean') {
      throw new Error('A source chunk does not match the expected schema.');
    }
    if (seen.has(chunk.id)) throw new Error('Duplicate chunk ID. Review input and redirects before ingestion.');
    seen.add(chunk.id);
    if (chunk.sourceUrl !== page.url && chunk.sourceUrl !== page.loadedUrl) throw new Error('Chunk source does not match its page.');
    if (typeof chunk.sectionUrl !== 'string' || chunk.sectionUrl.split('#')[0] !== chunk.sourceUrl.split('#')[0]) throw new Error('Chunk section URL does not match its source.');
    if (chunk.characterCount !== chunk.content.length) throw new Error('Chunk character count is inconsistent.');
    if (typeof page.crawledAt !== 'string' || Number.isNaN(Date.parse(page.crawledAt))) throw new Error('Missing crawl timestamp.');
    if (chunk.oversized) oversizedCount += 1;
    packets.push({
      id: chunk.id,
      content: chunk.content,
      sourceUrl: chunk.sourceUrl,
      sectionUrl: chunk.sectionUrl,
      title: chunk.title,
      headingPath: chunk.headingPath,
      contentHash: chunk.contentHash,
      crawledAt: page.crawledAt,
      characterCount: chunk.characterCount,
      oversized: chunk.oversized,
    });
  }
}
if (packets.length !== report.aiExport.returnedChunkCount || oversizedCount !== report.aiExport.oversizedChunkCount) throw new Error('Dataset chunk counts differ from RUN_SUMMARY.');
return [{ json: {
  coverage: {
    outcome: report.outcome,
    pageCount: pages.length,
    sourcePacketCount: packets.length,
    oversizedChunkCount: oversizedCount,
    followLinks: false,
    wholeSiteCompleteness: report.wholeSiteCompleteness,
    coverageNote: report.coverageNote,
    finishedAt: report.finishedAt,
  },
  sourcePackets: packets,
} }];
